mapper.update:
UPDATE users
SET status = 'ACTIVE',
    verification_token = NULL,
    verification_token_exp = NULL,
    updated_at = #{verifiedAt}
WHERE id = #{id}
  AND status = 'INACTIVE'
  AND verification_token = #{token}
  AND deleted_at IS NULL

mapper.select:
SELECT *
FROM users
WHERE username   = #{username}
  AND user_email = #{userEmail}
  AND status = 'ACTIVE'
  AND deleted_at IS NULL

mapper.update:
UPDATE users
SET reset_token      = #{tokenHash},
    reset_token_exp  = #{expiresAt}
WHERE id = #{id}

mapper.select:
SELECT *
FROM users
WHERE id = #{id}

SELECT profile_image
FROM users
WHERE username = #{username}

SELECT COUNT(*)
FROM users
WHERE nickname = #{nickname}
  AND id <> #{userId}

mapper.update:
UPDATE users
SET nickname = #{nickname}

    , profile_image = #{profileImage}

WHERE id = #{userId}
  AND status = 'ACTIVE'
  AND deleted_at IS NULL

mapper.select:
SELECT id, username, nickname, user_email, user_role, status, created_at
FROM users

ORDER BY created_at DESC, id DESC
LIMIT #{limit}
OFFSET #{offset}
